const fs = require('fs');

const [N, T] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let answer;
if (T === 0) {
  answer = N;
} else if (T === 1) {
  answer = N * (N - 1);
} else {
  answer = N * (N - 1) * (N - 2) / 6;
}

console.log(answer);
